  if(first<40) out=[0,first];
  else if(first<80) out=[1,first-40];
  else out=[2,first-80];
  var v=0;
  for(var i=1;i<bytes.length;i++){
    v=v*128+(bytes[i]&0x7f);
    if(!(bytes[i]&0x80)){ out.push(v); v=0; }
  }
  return out.join('.');
}

/* ---- SSH wire format（RFC 4251 §5）：一串 uint32 长度前缀的二进制块 ---- */
function sshStr(bytes){
  var n=bytes.length;
  return [(n>>>24)&0xff,(n>>>16)&0xff,(n>>>8)&0xff,n&0xff].concat(bytes);
}
function sshRead(buf){
  var out=[],i=0,trunc=null;
  while(i<buf.length){
    if(i+4>buf.length){ trunc={at:i, reason:'长度前缀不足 4 字节'}; break; }
    var n=((buf[i]<<24)|(buf[i+1]<<16)|(buf[i+2]<<8)|buf[i+3])>>>0;
    i+=4;
    if(n>buf.length-i){ trunc={at:i, reason:'声明 '+n+' 字节，实际只剩 '+(buf.length-i)+' 字节'}; break; }
    out.push(buf.slice(i,i+n)); i+=n;
  }
  return {fields:out, trunc:trunc, consumed:i};
}
function bitLen(bytes){
  var i=0;
  while(i<bytes.length && bytes[i]===0) i++;
  if(i===bytes.length) return 0;
  var b=bytes[i], n=(bytes.length-i-1)*8;
  while(b){ n++; b>>=1; }
  return n;
}
function wrap64(s,width){
  width=width||64;
  var out=[];
  for(var i=0;i<s.length;i+=width) out.push(s.slice(i,i+width));
  return out.join('\n');
}
function pemWrap(label, der){
  return '-----BEGIN '+label+'-----\n'+wrap64(b64encode(der),64)+'\n-----END '+label+'-----';
}
function pemUnwrap(text){
  var m=/-----BEGIN ([A-Z0-9 ]+)-----([\s\S]*?)-----END \1-----/.exec(String(text));
  if(!m) return {error:'没找到成对的 PEM 头尾（-----BEGIN X----- / -----END X-----）'};
  var body=m[2].replace(/[\s\r\n]/g,'');
  if(!body) return {error:'PEM 头尾之间是空的'};
  try { return {label:m[1], der:b64decode(body)}; }
  catch(e){ return {error:'PEM 主体不是合法 base64：'+e.message}; }
}


/* ============ OpenSSH 公钥工坊 ============
