   全部离线：指纹是本地算的 SHA-256/MD5，randomart 是本地跑的 drunken bishop。 */

var SSH_TYPES = {
  'ssh-rsa':                            {label:'RSA',          kind:'rsa',     names:['e','n']},
  'ssh-dss':                            {label:'DSA',          kind:'dsa',     names:['p','q','g','y']},
  'ecdsa-sha2-nistp256':                {label:'ECDSA P-256',  kind:'ecdsa',   names:['curve','Q']},
  'ecdsa-sha2-nistp384':                {label:'ECDSA P-384',  kind:'ecdsa',   names:['curve','Q']},
  'ecdsa-sha2-nistp521':                {label:'ECDSA P-521',  kind:'ecdsa',   names:['curve','Q']},
  'ssh-ed25519':                        {label:'Ed25519',      kind:'ed25519', names:['A']},
  'sk-ssh-ed25519@openssh.com':         {label:'Ed25519-SK',   kind:'ed25519', names:['A','application'], sk:true},
  'sk-ecdsa-sha2-nistp256@openssh.com': {label:'ECDSA-SK',     kind:'ecdsa',   names:['curve','Q','application'], sk:true}
