function fpSha256(blob){ return 'SHA256:'+b64encode(sha256Bytes(blob)).replace(/=+$/,''); }
function fpMd5(blob){ return 'MD5:'+colonHex(md5Bytes(blob)); }

/* SSH wire 游标读取器：证书里混着 uint64 和 string，纯 sshRead 扫不动。 */
function reader(buf){
  var i=0;
  var R={
    left:function(){ return buf.length-i; },
    pos:function(){ return i; },
    u32:function(){
      if(i+4>buf.length) throw new Error('读 uint32 时数据不足（偏移 '+i+'）');
      var n=((buf[i]<<24)|(buf[i+1]<<16)|(buf[i+2]<<8)|buf[i+3])>>>0; i+=4; return n;
    },
    u64:function(){
      if(i+8>buf.length) throw new Error('读 uint64 时数据不足（偏移 '+i+'）');
      var hi=((buf[i]<<24)|(buf[i+1]<<16)|(buf[i+2]<<8)|buf[i+3])>>>0;
      var lo=((buf[i+4]<<24)|(buf[i+5]<<16)|(buf[i+6]<<8)|buf[i+7])>>>0;
      i+=8; return hi*4294967296+lo;
    },
    str:function(){
      var n=R.u32();
      if(i+n>buf.length) throw new Error('读 string 时数据不足：声明 '+n+' 字节，只剩 '+(buf.length-i)+' 字节');
      var b=buf.slice(i,i+n); i+=n; return b;
    }
  };
  return R;
}

function parseOptions(str){
  var out=[],cur='',q=false,i=0;
  while(i<=str.length){
    var ch=i<str.length?str.charAt(i):null;
    if(ch===null || (ch===','&&!q)){
      if(cur.length){
        var eq=cur.indexOf('=');
        var name = eq<0 ? cur : cur.slice(0,eq);
        var val  = eq<0 ? null : cur.slice(eq+1);
        if(val!==null && val.charAt(0)==='"' && val.charAt(val.length-1)==='"' && val.length>1)
          val=val.slice(1,-1).replace(/\\"/g,'"').replace(/\\\\/g,'\\');
        out.push({name:name, value:val, raw:cur});
      }
      cur=''; i++; continue;
    }
    if(ch==='\\' && q){ cur+=ch+(str.charAt(i+1)||''); i+=2; continue; }
    if(ch==='"'){ q=!q; }
    cur+=ch; i++;
  }
  return out;
}

function looksLikeKeyType(w){
  return !!SSH_TYPES[w] || /^(ssh-|ecdsa-sha2-|sk-)/.test(w);
}

function parseLine(line){
  var raw=String(line===undefined?'':line).replace(/\r$/,'');
  var t=raw.trim();
  if(!t) return {kind:'blank', raw:raw};
  if(t.charAt(0)==='#') return {kind:'comment', raw:raw, text:t};
  var marker=null;
  if(t.charAt(0)==='@'){
    var sp=t.search(/\s/);
    if(sp<0) return {kind:'error', raw:raw, error:'只有标记 "'+t+'"，后面没跟密钥'};
    marker=t.slice(0,sp); t=t.slice(sp).replace(/^\s+/,'');
  }
  var options=[], optRaw='';
  var firstWord=t.split(/\s+/)[0]||'';
  if(!looksLikeKeyType(firstWord)){
    var i=0,q=false;
    while(i<t.length){
      var ch=t.charAt(i);
      if(ch==='\\' && q){ i+=2; continue; }
      if(ch==='"'){ q=!q; i++; continue; }
      if(!q && /\s/.test(ch)) break;
      i++;
    }
    if(q) return {kind:'error', raw:raw, error:'选项里的双引号没有闭合'};
    optRaw=t.slice(0,i);
    t=t.slice(i).replace(/^\s+/,'');
    options=parseOptions(optRaw);
  }
  var parts=t.length?t.split(/\s+/):[];
  var type=parts[0]||'';
  if(!type) return {kind:'error', raw:raw, error:'没解析出密钥类型'};
  if(!looksLikeKeyType(type)) return {kind:'error', raw:raw, error:'"'+type+'" 不像 SSH 公钥类型（应形如 ssh-ed25519 / ssh-rsa / ecdsa-sha2-nistp256）'};
  var b64=parts[1]||'';
  if(!b64) return {kind:'error', raw:raw, error:'密钥类型 "'+type+'" 后面没有 base64 密钥体'};
  return {kind:'key', raw:raw, marker:marker, options:options, optionsRaw:optRaw,
          type:type, b64:b64, comment:parts.slice(2).join(' ')};
}

/* known_hosts 的第一列是主机名模式，跟 authorized_keys 的选项列位置一样但语义不同。 */
function parseKnownHostsLine(line){
  var raw=String(line===undefined?'':line).replace(/\r$/,'');
  var t=raw.trim();
  if(!t) return {kind:'blank', raw:raw};
  if(t.charAt(0)==='#') return {kind:'comment', raw:raw, text:t};
  var marker=null;
  if(t.charAt(0)==='@'){
    var sp=t.search(/\s/);
    if(sp<0) return {kind:'error', raw:raw, error:'只有标记 "'+t+'"'};
    marker=t.slice(0,sp); t=t.slice(sp).replace(/^\s+/,'');
  }
  var parts=t.split(/\s+/);
  if(parts.length<3) return {kind:'error', raw:raw, error:'known_hosts 至少要有「主机 类型 密钥」三列'};
  var hostField=parts[0], hashed=null;
  if(hostField.charAt(0)==='|'){
    var seg=hostField.split('|');
    if(seg.length!==4 || seg[1]!=='1') return {kind:'error', raw:raw, error:'哈希主机名格式应为 |1|salt|hash'};
    hashed={salt:seg[2], hash:seg[3]};
  }
  return {kind:'host', raw:raw, marker:marker, hostField:hostField, hashed:hashed,
          patterns:hashed?null:hostField.split(','), type:parts[1], b64:parts[2],
          comment:parts.slice(3).join(' ')};
}

function hashKnownHost(host, salt){
  var s=salt&&salt.length?salt:null;
  if(!s){ s=[]; for(var i=0;i<20;i++) s.push(0); }
  return '|1|'+b64encode(s)+'|'+b64encode(hmacSha1(s, utf8Bytes(String(host))));
}
function matchHashedHost(entry, host){
  if(!entry || !entry.hashed) return false;
  var salt, want;
  try { salt=b64decode(entry.hashed.salt); want=b64decode(entry.hashed.hash); }
  catch(e){ return false; }
  var got=hmacSha1(salt, utf8Bytes(String(host)));
  if(got.length!==want.length) return false;
  for(var i=0;i<got.length;i++) if(got[i]!==want[i]) return false;
  return true;
}
/* known_hosts 的明文模式支持 * 和 ?，还允许 [host]:port 写法。 */
function matchHostPattern(pattern, host){
  var neg=false, p=String(pattern);
  if(p.charAt(0)==='!'){ neg=true; p=p.slice(1); }
  var rx=new RegExp('^'+p.replace(/[.+^${}()|[\]\\]/g,'\\$&').replace(/\*/g,'.*').replace(/\?/g,'.')+'$');
  var hit=rx.test(String(host));
  return neg ? (hit?'deny':false) : hit;
}

function decodeKey(type, b64){
  var blob;
  try { blob=b64decode(b64); }
  catch(e){ return {error:'密钥体不是合法 base64：'+e.message}; }
  if(!blob.length) return {error:'密钥体解出来是 0 字节'};
  var out={blob:blob, bytes:blob.length, fields:[], warnings:[]};
  var R=reader(blob), inner;
  try { inner=bytesToUtf8(R.str()); }
  catch(e){ return {error:'读取内部类型失败：'+e.message, blob:blob}; }
  out.inner=inner;
  out.isCert = inner.indexOf(CERT_SUFFIX)>0;
  var base = out.isCert ? inner.slice(0, inner.length-CERT_SUFFIX.length) : inner;
  if(base==='ssh-rsa-cert-v01') base='ssh-rsa';
  out.base=base;
  if(type && inner!==type)
    out.mismatch='行首写的是 "'+type+'"，密钥体里却是 "'+inner+'"——多半是复制时串了行';
  var spec=SSH_TYPES[base];
  out.label = spec ? spec.label : base;
  out.fields.push({name:'type', text:inner, bytes:utf8Bytes(inner).length});
  try {
    if(out.isCert) out.fields.push({name:'nonce', hex:toHex(R.str()), note:'防重放随机数'});
    if(!spec){ out.warnings.push('未知密钥类型 "'+base+'"，后续字段不再逐个拆解'); out.rest=R.left(); return out; }
    var names=spec.names, vals=[];
    for(var i=0;i<names.length;i++){
      var v=R.str(); vals.push(v);
      var f={name:names[i], bytes:v.length};
      if(names[i]==='curve'||names[i]==='application') f.text=bytesToUtf8(v);
      else f.hex=toHex(v);
      out.fields.push(f);
    }
    if(spec.kind==='rsa'){
      out.bits=bitLen(vals[1]);
      out.exponent=parseInt(toHex(vals[0]),16);
      out.detail='e='+out.exponent+' · n 为 '+out.bits+' 位';
    } else if(spec.kind==='dsa'){
      out.bits=bitLen(vals[0]);
      out.detail='p 为 '+out.bits+' 位';
    } else if(spec.kind==='ecdsa'){
      var cname=bytesToUtf8(vals[0]), ci=CURVES[cname];
      out.curve=cname;
      out.bits=ci?ci.bits:0;
      out.jose=ci?ci.jose:null;
      var Q=vals[1];
      if(Q.length && Q[0]!==0x04) out.warnings.push('公钥点首字节是 0x'+('0'+Q[0].toString(16)).slice(-2)+'，不是未压缩点 0x04，OpenSSH 不接受压缩点');
      if(ci && Q.length!==1+2*ci.coord) out.warnings.push('曲线 '+cname+' 的公钥点应为 '+(1+2*ci.coord)+' 字节，实际 '+Q.length+' 字节');
      if(base.indexOf(cname)<0 && !spec.sk) out.warnings.push('类型名里的曲线与字段里的曲线 "'+cname+'" 对不上');
      out.detail=cname+' 未压缩点，'+Q.length+' 字节';
    } else if(spec.kind==='ed25519'){
      out.bits=256;
      if(vals[0].length!==32) out.warnings.push('Ed25519 公钥应为 32 字节，实际 '+vals[0].length+' 字节');
      out.detail='32 字节曲线点';
      if(spec.sk) out.detail+=' · FIDO2 application='+bytesToUtf8(vals[names.indexOf('application')]||[]);
    }
    if(out.isCert){
      var c={};
      c.serial=R.u64();
      var ct=R.u32();
      c.certType = ct===1?'用户证书':(ct===2?'主机证书':'未知类型 '+ct);
      c.keyId=bytesToUtf8(R.str());
      var pr=reader(R.str()), principals=[];
      while(pr.left()>0) principals.push(bytesToUtf8(pr.str()));
      c.principals=principals;
      c.validAfter=R.u64();
      c.validBefore=R.u64();
      c.criticalBytes=R.str().length;
      c.extensionBytes=R.str().length;
      R.str();
      var sk=R.str();
      c.signatureKeyFp=fpSha256(sk);
      try { c.signatureKeyType=bytesToUtf8(reader(sk).str()); } catch(e2){ c.signatureKeyType='?'; }
      c.signatureBytes=R.str().length;
      out.cert=c;
    }
  } catch(e){
    out.error='SSH wire 解析中断：'+e.message;
    return out;
  }
  out.rest=R.left();
  if(out.rest>0) out.warnings.push('密钥体末尾还剩 '+out.rest+' 字节没被消费，格式可能不对');
  out.sha256=fpSha256(blob);
  out.md5=fpMd5(blob);
  return out;
}

/* OpenSSH 的 drunken bishop：拿指纹当随机游走的方向序列，落点次数决定字符。
   照着 sshkey_fingerprint_randomart() 的实现逐行搬过来，包括边框拼法。 */
var ART_CHARS=' .o+=*BOX@%&#/^SE';
function randomart(digest, title, footer){
  var X=17, Y=9;
  var f=[],x=Math.floor(X/2),y=Math.floor(Y/2),i,j;
  for(i=0;i<X;i++){ f[i]=[]; for(j=0;j<Y;j++) f[i][j]=0; }
  for(i=0;i<digest.length;i++){
    var input=digest[i];
    for(var k=0;k<4;k++){
      x += (input&0x1) ? 1 : -1;
      y += (input&0x2) ? 1 : -1;
      x = Math.max(0, Math.min(X-1, x));
      y = Math.max(0, Math.min(Y-1, y));
      if(f[x][y] < ART_CHARS.length-2) f[x][y]++;
      input >>= 2;
    }
  }
  f[Math.floor(X/2)][Math.floor(Y/2)] = ART_CHARS.length-2;
  f[x][y] = ART_CHARS.length-1;
  function border(text){
    var t=text?('['+text+']'):'';
    if(t.length>X) t=t.slice(0,X);
    var lead=Math.floor((X-t.length)/2);
    var s='+';
    for(var q=0;q<lead;q++) s+='-';
    s+=t;
    for(var q2=lead+t.length;q2<X;q2++) s+='-';
    return s+'+';
  }
  var lines=[border(title)];
  for(j=0;j<Y;j++){
    var row='|';
    for(i=0;i<X;i++) row+=ART_CHARS.charAt(f[i][j]);
    lines.push(row+'|');
  }
  lines.push(border(footer||'SHA256'));
  return lines.join('\n');
}

function analyze(parsed, dec){
  var out=[];
  function add(level,msg){ out.push({level:level, msg:msg}); }
  if(parsed.marker==='@cert-authority')
    add('warn','这一行是 @cert-authority：由该 CA 签发的任何证书都会被无条件接受，务必配合 principals= 限定范围');
  if(parsed.marker==='@revoked')
    add('info','这一行是 @revoked 吊销标记，匹配到的密钥会被直接拒绝');
  if(dec.error){ add('bad','解析失败：'+dec.error); return out; }
  if(dec.mismatch) add('bad', dec.mismatch);
  for(var w=0;w<(dec.warnings||[]).length;w++) add('warn', dec.warnings[w]);

  if(dec.base==='ssh-dss')
    add('bad','DSA 从 OpenSSH 7.0 起默认关闭，9.8 起编译期就被移除，任何现存 ssh-dss 都该立刻替换');
  if(dec.base==='ssh-rsa'){
    if(dec.bits<1024) add('bad','RSA 只有 '+dec.bits+' 位，属于可被现成算力打穿的级别');
    else if(dec.bits<2048) add('bad','RSA '+dec.bits+' 位低于 2048 位下限，OpenSSH 8.2+ 会直接拒绝');
    else if(dec.bits<3072) add('info','RSA '+dec.bits+' 位仍在安全线内，长期使用建议升到 3072 位或直接换 Ed25519');
    else add('ok','RSA '+dec.bits+' 位，强度充足');
    if(dec.exponent!==65537) add('warn','公钥指数 e='+dec.exponent+' 不是常规的 65537，来路需要确认');
    add('info','注意区分密钥类型与签名算法：ssh-rsa 密钥没问题，但 SHA-1 签名算法 ssh-rsa 自 OpenSSH 8.8 起默认禁用，服务端需支持 rsa-sha2-256/512');
  }
  if(dec.base==='ssh-ed25519') add('ok','Ed25519：128 位安全强度、68 字节公钥、抗侧信道，目前的默认推荐');
  if((dec.base||'').indexOf('ecdsa-sha2-')===0) add('ok','ECDSA '+(dec.curve||'')+'：强度够用，但实现对随机数敏感，同等条件下 Ed25519 更省心');
  if(SSH_TYPES[dec.base] && SSH_TYPES[dec.base].sk)
    add('ok','FIDO2 硬件密钥：私钥留在安全芯片里，配合 verify-required 可做到「插着还得摸一下」');

  if(!parsed.comment) add('info','这一行没有注释，出事时无法从 authorized_keys 里认出这是谁的钥匙，建议补上 用户@主机 或用途');
  if(dec.isCert && dec.cert){
    var c=dec.cert;
    add('info','这是 OpenSSH 证书：'+c.certType+'，key id="'+c.keyId+'"，principals='+(c.principals.length?c.principals.join(','):'(全部)'));
    if(!c.principals.length) add('warn','证书没有限定 principals，等于对所有用户名都有效');
    if(c.validBefore>=18446744073709551615 || c.validBefore>4102444800)
