  for(var i=0;i<(parsed.options||[]).length;i++){
    var o=parsed.options[i], meta=OPTIONS[o.name];
    names[o.name]=true;
    if(o.name==='restrict') hasRestrict=true;
    if(o.name==='command') hasCommand=true;
    if(o.name==='from') hasFrom=true;
    if(!meta){ add('warn','未知选项 "'+o.name+'"：OpenSSH 遇到不认识的选项会整行拒绝，登录会直接失败'); continue; }
    if(meta.arg && o.value===null) add('bad','选项 '+o.name+' 需要 ="值" 形式的参数');
    if(!meta.arg && o.value!==null) add('bad','选项 '+o.name+' 不接受参数，却写成了 '+o.raw);
    if(meta.risk==='warn') reopened.push(o.name);
  }
  if(hasCommand && !hasRestrict && !names['no-pty'])
    add('warn','写了 command= 却没有 restrict 或 no-pty：客户端仍可申请终端与端口转发，强制命令不等于沙箱');
  if((parsed.options||[]).length===0)
    add('info','这一行没有任何限制选项。若是 CI / 部署专用密钥，建议至少加 restrict 与 from="…"');
  else if(!hasRestrict && !names['no-port-forwarding'])
    add('info','没有 restrict 也没有 no-port-forwarding，这把钥匙可以把机器当跳板做端口转发');
  if(hasFrom) add('ok','带 from= 来源限定，攻击面明显收窄');
  if(hasRestrict && reopened.length) add('info','restrict 之后又单独放开了：'+reopened.join('、')+'，请确认是有意为之');
  return out;
}

function buildLine(opts, type, b64, comment){
  var parts=[];
  var o=(opts||[]).filter(function(s){ return s && String(s).length; });
  if(o.length) parts.push(o.join(','));
  parts.push(type||'ssh-ed25519');
  parts.push(b64||'');
  if(comment) parts.push(comment);
  return parts.join(' ');
}

function parseFile(text){
  var lines=String(text===undefined?'':text).split(/\n/);
  var out=[];
  for(var i=0;i<lines.length;i++){
    var p=parseLine(lines[i]);
    p.line=i+1;
    if(p.kind==='key'){
      p.decoded=decodeKey(p.type, p.b64);
      p.issues=analyze(p, p.decoded);
    }
    out.push(p);
  }
  return out;
}

function fileStats(entries){
  var s={total:0, byType:{}, errors:0, dupes:[], weakest:null};
  var seen={};
  for(var i=0;i<entries.length;i++){
    var e=entries[i];
    if(e.kind==='error'){ s.errors++; continue; }
    if(e.kind!=='key') continue;
    s.total++;
    var d=e.decoded||{};
    if(d.error){ s.errors++; continue; }
    var lbl=d.label||e.type;
    s.byType[lbl]=(s.byType[lbl]||0)+1;
    var fp=d.sha256;
    if(fp){
      if(seen[fp]) s.dupes.push({fp:fp, lines:[seen[fp], e.line]});
      else seen[fp]=e.line;
    }
    var score = d.base==='ssh-dss' ? 0 : (d.base==='ssh-rsa' ? d.bits : (d.base==='ssh-ed25519' ? 3072 : (d.bits||0)*12));
    if(s.weakest===null || score<s.weakest.score) s.weakest={line:e.line, label:lbl, score:score};
  }
  return s;
}

